class Solution {
public:
    int countOfPairs(vector<int>& nums) {
        const int mod = 1e9 + 7;
        int n = nums.size();
        int max_val = 0;
        for (int x : nums) max_val = max(max_val, x);
        vector<long long> dp(max_val + 1, 0);
        for (int v = 0; v <= nums[0]; ++v) dp[v] = 1;

        for (int i = 1; i < n; ++i) {
            vector<long long> pref(max_val + 2, 0);
            for (int v = 0; v <= max_val; ++v) {
                pref[v + 1] = (pref[v] + dp[v]) % mod;
            }
            vector<long long> next_dp(max_val + 1, 0);
            int diff = max(0, nums[i] - nums[i - 1]);
            for (int v = 0; v <= nums[i]; ++v) {
                int limit = min(v, v - diff);
                if (limit >= 0) {
                    next_dp[v] = pref[limit + 1];
                }
            }
            dp = move(next_dp);
        }
        long long ans = 0;
        for (long long v : dp) ans = (ans + v) % mod;
        return ans;
    }
};

class Solution {
    public int countOfPairs(int[] nums) {
        int mod = 1_000_000_007;
        int n = nums.length;
        int maxVal = 0;
        for (int x : nums) maxVal = Math.max(maxVal, x);
        long[] dp = new long[maxVal + 1];
        for (int v = 0; v <= nums[0]; ++v) dp[v] = 1;

        for (int i = 1; i < n; ++i) {
            long[] pref = new long[maxVal + 2];
            for (int v = 0; v <= maxVal; ++v) {
                pref[v + 1] = (pref[v] + dp[v]) % mod;
            }
            long[] nextDp = new long[maxVal + 1];
            int diff = Math.max(0, nums[i] - nums[i - 1]);
            for (int v = 0; v <= nums[i]; ++v) {
                int limit = Math.min(v, v - diff);
                if (limit >= 0) {
                    nextDp[v] = pref[limit + 1];
                }
            }
            dp = nextDp;
        }
        long ans = 0;
        for (long v : dp) ans = (ans + v) % mod;
        return (int) ans;
    }
}

